"""Candidate opportunity universe (100 entries).

Each candidate carries the 18 fields required by the research brief plus
evidence tags and the elimination-gate outcome. Evidence classes:
[F] fact, [D] dataset-derived, [E] evidence-backed estimate, [M] model
assumption, [I] inference, [S] speculation. Source ids refer to
research/sources.csv.

Gates (applied in order; first failure eliminates):
  G1 measurable economic loss with a traceable source or clear mechanism
  G2 identifiable buyer with budget authority and a recurring trigger
  G3 target segment not already dominated by well-funded incumbents
  G4 feasible for a seed-stage team (licensing, data access, sales cycle)
  G5 timing window open in Sep 2026 (not closed, not deferred past 2027)
  G6 survives AI-commoditization and platform-dependency tests
"""
from __future__ import annotations

FIELDS = [
    "id", "name", "sector", "problem", "customer", "workaround", "competitors",
    "economic_loss", "wtp", "market_size", "growth", "competition",
    "technical_difficulty", "regulatory_difficulty", "distribution_difficulty",
    "retention_mechanism", "monetization", "moat", "why_now",
    "why_unsolved", "falsifier", "sources", "failed_gate", "gate_reason",
]


def c(i, name, sector, problem, customer, workaround, competitors, loss, wtp,
      market, growth, competition, tech, reg, dist, retention, monetization,
      moat, why_now, why_unsolved, falsifier, sources, failed_gate, reason):
    return dict(zip(FIELDS, [i, name, sector, problem, customer, workaround,
                             competitors, loss, wtp, market, growth, competition,
                             tech, reg, dist, retention, monetization, moat,
                             why_now, why_unsolved, falsifier, sources,
                             failed_gate, reason]))


